import React, { useState, useEffect, useRef } from 'react';
import api, { LensService, InventoryService, DegreePolicyService } from '../services/api';
import { Sparkles, DollarSign, Plus, Check, Barcode, Keyboard, Layers, RefreshCw, AlertTriangle, CheckCircle, PackagePlus, FileText } from 'lucide-react';

const PRESET_OPTIONS = {
  LP_GRADE: [
    { paramKey: 'lp_incolor_150', name: "LP Incolor 1.50", index: 1.50, material: "CR-39", treatment: "Incolor", route: "EXPRESSA_FACETAMENTO", defaultBase: "60.00", defaultOver: "80.00" },
    { paramKey: 'lp_ar_156', name: "LP AR 1.56", index: 1.56, material: "Resina", treatment: "AR", route: "EXPRESSA_FACETAMENTO", defaultBase: "75.00", defaultOver: "95.00" },
    { paramKey: 'lp_filtro_azul_ar_156', name: "LP Filtro Azul AR 1.56", index: 1.56, material: "Resina", treatment: "Filtro Azul AR", route: "EXPRESSA_FACETAMENTO", defaultBase: "95.00", defaultOver: "125.00" },
    { paramKey: 'lp_poly_ar_159', name: "LP POLY AR 1.59", index: 1.59, material: "Policarbonato", treatment: "AR", route: "EXPRESSA_FACETAMENTO", defaultBase: "110.00", defaultOver: "140.00" },
    { paramKey: 'lp_poly_filtro_azul_ar_159', name: "LP POLY FILTRO AZUL AR 1.59", index: 1.59, material: "Policarbonato", treatment: "Filtro Azul AR", route: "EXPRESSA_FACETAMENTO", defaultBase: "130.00", defaultOver: "165.00" },
    { paramKey: 'lp_photo_ar_156', name: "LP PHOTO AR 1.56", index: 1.56, material: "Resina", treatment: "Photo AR", route: "EXPRESSA_FACETAMENTO", defaultBase: "145.00", defaultOver: "185.00" },
    { paramKey: 'lp_photo_filtro_azul_ar_156', name: "LP PHOTO FILTRO AZUL AR 1.56", index: 1.56, material: "Resina", treatment: "Photo Filtro Azul AR", route: "EXPRESSA_FACETAMENTO", defaultBase: "170.00", defaultOver: "215.00" }
  ],
  MF_ACB: [
    { name: "MF ACB Incolor 1.50", index: 1.50, material: "CR-39", treatment: "Incolor", route: "EXPRESSA_FACETAMENTO" },
    { name: "MF ACB AR 1.56", index: 1.56, material: "Resina", treatment: "AR", route: "EXPRESSA_FACETAMENTO" },
    { name: "MF ACB Filtro Azul AR 1.56", index: 1.56, material: "Resina", treatment: "Filtro Azul AR", route: "EXPRESSA_FACETAMENTO" },
    { name: "MF ACB PHOTO AR 1.56", index: 1.56, material: "Resina", treatment: "Photo AR", route: "EXPRESSA_FACETAMENTO" },
    { name: "MF ACB PHOTO FILTRO AZUL AR 1.56", index: 1.56, material: "Resina", treatment: "Photo Filtro Azul AR", route: "EXPRESSA_FACETAMENTO" }
  ],
  GRADE_167: [
    { name: "1.67 AR", index: 1.67, material: "Alto Índice 1.67", treatment: "AR", route: "EXPRESSA_FACETAMENTO" },
    { name: "1.67 FA", index: 1.67, material: "Alto Índice 1.67", treatment: "Filtro Azul AR", route: "EXPRESSA_FACETAMENTO" }
  ],
  BLOCO_VS: [
    { name: "Bloco VS INCOLOR", index: 1.50, material: "CR-39", treatment: "Incolor", route: "SURFACAGEM_CNC" },
    { name: "Bloco VS AR", index: 1.56, material: "Resina", treatment: "AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco VS FILTRO AZUL AR", index: 1.56, material: "Resina", treatment: "Filtro Azul AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco VS PHOTO AR", index: 1.56, material: "Resina", treatment: "Photo AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco VS PHOTO FILTRO AZUL AR", index: 1.56, material: "Resina", treatment: "Photo Filtro Azul AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco VS 1.67 AR", index: 1.67, material: "Alto Índice 1.67", treatment: "AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco VS 1.67 FA", index: 1.67, material: "Alto Índice 1.67", treatment: "Filtro Azul AR", route: "SURFACAGEM_CNC" }
  ],
  MF_BLOCO: [
    { name: "Bloco MF INCOLOR 1.50", index: 1.50, material: "CR-39", treatment: "Incolor", route: "SURFACAGEM_CNC" },
    { name: "Bloco MF AR 1.56", index: 1.56, material: "Resina", treatment: "AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco MF FILTRO AZUL AR 1.56", index: 1.56, material: "Resina", treatment: "Filtro Azul AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco MF PHOTO AR 1.56", index: 1.56, material: "Resina", treatment: "Photo AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco MF PHOTO FILTRO AZUL AR 1.56", index: 1.56, material: "Resina", treatment: "Photo Filtro Azul AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco MF 1.67 AR", index: 1.67, material: "Alto Índice 1.67", treatment: "AR", route: "SURFACAGEM_CNC" },
    { name: "Bloco MF 1.67 FA", index: 1.67, material: "Alto Índice 1.67", treatment: "Filtro Azul AR", route: "SURFACAGEM_CNC" }
  ]
};

export default function UnifiedLensRegister({ initialData = null, onComplete = null }) {
  const [subTab, setSubTab] = useState('bip_entry'); // 'bip_entry' ou 'preset_models'

  // Modelos existentes cadastrados no sistema
  const [models, setModels] = useState([]);
  const [selectedModelId, setSelectedModelId] = useState('');

  // BIP e Inserção de Saldo
  const [barcode, setBarcode] = useState(initialData?.barcode || '');
  const [bipInput, setBipInput] = useState('');
  const [quantity, setQuantity] = useState(initialData?.quantity || 1);
  const [presetQuantity, setPresetQuantity] = useState(initialData?.quantity || 1);
  const [spherical, setSpherical] = useState(initialData?.spherical || '');
  const [cylindrical, setCylindrical] = useState(initialData?.cylindrical || '');
  const [baseCurve, setBaseCurve] = useState(initialData?.baseCurve || '');
  const [addition, setAddition] = useState(initialData?.addition || '');
  const [eye, setEye] = useState(initialData?.eye || 'OD');
  const [locationTag, setLocationTag] = useState(initialData?.locationTag || '');

  // Campos explícitos para Marca e Modelo no Formulário Principal (bip_entry)
  const [bipBrand, setBipBrand] = useState('');
  const [bipName, setBipName] = useState('');
  const [bipMatrixType, setBipMatrixType] = useState(initialData?.matrixType || 'LP_GRADE');
  const [bipMaterial, setBipMaterial] = useState('Resina');
  const [bipTreatment, setBipTreatment] = useState('Incolor');
  const [bipRefractiveIndex, setBipRefractiveIndex] = useState('1.56');

  // Configuração de Modelo & Presets
  const [matrixType, setMatrixType] = useState('LP_GRADE');
  const [selectedPresetIndex, setSelectedPresetIndex] = useState('');
  const [customBrand, setCustomBrand] = useState('');
  const [customName, setCustomName] = useState('');
  const [customMaterial, setCustomMaterial] = useState('Resina');
  const [customRefractiveIndex, setCustomRefractiveIndex] = useState('1.56');
  const [customTreatment, setCustomTreatment] = useState('Incolor');
  const [costPrice, setCostPrice] = useState('25.00');
  const [salePrice, setSalePrice] = useState('75.00');
  const [salePriceOverThreshold, setSalePriceOverThreshold] = useState('95.00');
  const [degreeThreshold, setDegreeThreshold] = useState('2.00');
  const [systemParams, setSystemParams] = useState(null);
  const [degreePolicy, setDegreePolicy] = useState(null);

  // Grau da Lente e Parâmetros a Cadastrar no Preset
  const [presetSpherical, setPresetSpherical] = useState(initialData?.spherical || '');
  const [presetCylindrical, setPresetCylindrical] = useState(initialData?.cylindrical || '');
  const [presetBaseCurve, setPresetBaseCurve] = useState('');
  const [presetAddition, setPresetAddition] = useState('');
  const [presetEye, setPresetEye] = useState('OD');
  const [presetBarcode, setPresetBarcode] = useState('');
  const [presetLocationTag, setPresetLocationTag] = useState('GAVETA-01');

  // Tabela Dinâmica por Faixa de Grau (Exclusivo LP_GRADE)
  const [degreeRanges, setDegreeRanges] = useState([
    { minSph: '-4.00', maxSph: '4.00', minCyl: '-2.00', maxCyl: '0.00', price: '75.00' },
    { minSph: '-12.00', maxSph: '12.00', minCyl: '-4.00', maxCyl: '0.00', price: '95.00' }
  ]);

  const [saving, setSaving] = useState(false);
  const [scanning, setScanning] = useState(false);
  const [feedback, setFeedback] = useState(null);

  const barcodeInputRef = useRef(null);

  const getPresetLiveCalculatedPrice = () => {
    const sphVal = Math.abs(parseFloat(presetSpherical) || 0.0);
    const thresh = parseFloat(degreeThreshold || 2.00);
    const isHigh = sphVal > thresh;
    const price = isHigh ? parseFloat(salePriceOverThreshold || 95.00) : parseFloat(salePrice || 75.00);
    return { sphVal, thresh, isHigh, price };
  };

  useEffect(() => {
    loadModels();
    loadSystemParameters();
  }, []);

  const loadSystemParameters = async () => {
    try {
      const polRes = await DegreePolicyService.getPolicy();
      if (polRes.data) {
        setDegreePolicy(polRes.data);
        if (polRes.data.default_sale_price_le) setSalePrice(parseFloat(polRes.data.default_sale_price_le).toFixed(2));
        if (polRes.data.default_sale_price_gt) setSalePriceOverThreshold(parseFloat(polRes.data.default_sale_price_gt).toFixed(2));
        if (polRes.data.degree_threshold) setDegreeThreshold(parseFloat(polRes.data.degree_threshold).toFixed(2));
      }
      const sysRes = await api.get('/system-parameters/');
      if (sysRes.data) {
        setSystemParams(sysRes.data);
      }
    } catch (e) {
      console.warn("Erro ao carregar parâmetros do sistema:", e);
    }
  };

  useEffect(() => {
    if (initialData) {
      if (initialData.barcode) setBarcode(initialData.barcode);
      if (initialData.spherical) setSpherical(initialData.spherical);
      if (initialData.cylindrical) setCylindrical(initialData.cylindrical);
      if (initialData.matrixType) setMatrixType(initialData.matrixType);
    }
  }, [initialData]);

  const loadModels = async () => {
    try {
      const res = await LensService.getModels();
      setModels(res.data || []);
      if (res.data && res.data.length > 0) {
        setSelectedModelId(res.data[0].id);
      }
    } catch (err) {
      console.error("Erro ao carregar modelos:", err);
    }
  };

  const selectedPresetObj = selectedPresetIndex !== '' ? PRESET_OPTIONS[matrixType]?.[parseInt(selectedPresetIndex)] : null;

  // Atualiza automaticamente os preços e atributos do modelo quando um preset é selecionado
  useEffect(() => {
    if (selectedPresetObj) {
      setCustomMaterial(selectedPresetObj.material || '');
      setCustomRefractiveIndex(String(selectedPresetObj.index || '1.56'));
      setCustomTreatment(selectedPresetObj.treatment || '');

      const pk = selectedPresetObj.paramKey;
      let base = selectedPresetObj.defaultBase || '75.00';
      let over = selectedPresetObj.defaultOver || '95.00';
      let thresh = degreePolicy?.degree_threshold || '2.00';

      if (pk && systemParams) {
        if (systemParams[`${pk}_price_base`]) base = systemParams[`${pk}_price_base`];
        if (systemParams[`${pk}_price_over`]) over = systemParams[`${pk}_price_over`];
        if (systemParams[`${pk}_cyl_threshold`]) thresh = systemParams[`${pk}_cyl_threshold`];
      }

      setSalePrice(parseFloat(base).toFixed(2));
      setSalePriceOverThreshold(parseFloat(over).toFixed(2));
      setDegreeThreshold(parseFloat(thresh).toFixed(2));
    }
  }, [selectedPresetIndex, matrixType, systemParams]);

  // Processa bipagem instantânea via BIP
  const handleBipScan = async (e) => {
    e.preventDefault();
    const code = bipInput.trim();
    if (!code) return;

    setBipInput('');
    setScanning(true);
    setFeedback(null);

    try {
      const response = await InventoryService.scan(code);
      if (response.data.found) {
        setFeedback({
          type: 'success',
          message: `BIP Sucesso! Saldo incrementado (+1) para a dioptria bipada (${code}).`,
          detail: response.data.item ? `${response.data.item.lens_model?.brand || 'Lente'} | Grau: ${response.data.item.spherical || '0.00'} Esf` : ''
        });
      } else {
        setBarcode(code);
        setFeedback({
          type: 'warning',
          message: `Código BIP '${code}' é INÉDITO no estoque! Preencha as dioptrias abaixo e clique em Salvar para registrar no catálogo.`,
        });
      }
    } catch (err) {
      console.error(err);
      setBarcode(code);
      setFeedback({ type: 'warning', message: `Código '${code}' pronto para cadastro manual.` });
    } finally {
      setScanning(false);
    }
  };

  // Sincroniza campos de Marca, Modelo e Matriz quando um modelo é selecionado na lista
  useEffect(() => {
    if (selectedModelId === 'NEW_MODEL') {
      setBipBrand('');
      setBipName('');
      setBipMatrixType('LP_GRADE');
      setBipMaterial('Resina');
      setBipTreatment('Incolor');
      setBipRefractiveIndex('1.56');
    } else if (selectedModelId) {
      const found = models.find(m => String(m.id) === String(selectedModelId));
      if (found) {
        setBipBrand(found.brand || '');
        setBipName(found.name || found.brand || '');
        setBipMatrixType(found.matrix_type || 'LP_GRADE');
        setBipMaterial(found.material || 'Resina');
        setBipTreatment(found.treatment || 'Incolor');
        setBipRefractiveIndex(String(found.refractive_index || '1.56'));
      }
    }
  }, [selectedModelId, models]);

  const formatErrorMessage = (err, defaultMsg) => {
    const detail = err.response?.data?.detail;
    if (typeof detail === 'string') return detail;
    if (Array.isArray(detail)) {
      return detail.map(d => (typeof d === 'string' ? d : d.msg || JSON.stringify(d))).join(' | ');
    }
    if (detail && typeof detail === 'object') {
      return detail.msg || JSON.stringify(detail);
    }
    return err.message || defaultMsg;
  };

  // Salva Inserção Direta / Dioptria em Estoque
  const handleSaveInventoryGrade = async (e) => {
    e.preventDefault();
    setSaving(true);
    setFeedback(null);
    try {
      let modelIdToUse = selectedModelId;

      // Se o usuário selecionou 'NEW_MODEL' ou não tem modelo selecionado, cria novo modelo com Marca informada
      if (selectedModelId === 'NEW_MODEL' || !modelIdToUse || modelIdToUse === '') {
        if (!bipBrand.trim()) {
          alert("Informe a Marca da Lente.");
          setSaving(false);
          return;
        }
        const brandName = bipBrand.trim();
        const newModelPayload = {
          brand: brandName,
          name: brandName,
          matrix_type: bipMatrixType || 'LP_GRADE',
          material: bipMaterial || 'Resina',
          refractive_index: parseFloat(bipRefractiveIndex || 1.56),
          treatment: bipTreatment || 'Incolor',
          diameter: 70,
          cost_price: 25.00,
          sale_price: 75.00,
          degree_threshold: 2.00,
          sale_price_over_threshold: 95.00
        };
        const createdRes = await LensService.createModel(newModelPayload);
        modelIdToUse = createdRes.data.id;
        await loadModels();
      }

      const baseCode = (barcode && barcode.trim()) ? barcode.trim() : 'INT-' + Math.floor(1000000000 + Math.random() * 9000000000);
      const isMultifocal = (bipMatrixType === 'MF_ACB' || bipMatrixType === 'MF_BLOCO');

      if (isMultifocal && eye === 'OD_OE') {
        // Registra OD
        await InventoryService.registerFallback({
          barcode: `${baseCode}-OD`,
          lens_model_id: modelIdToUse,
          spherical: 0.0,
          cylindrical: 0.0,
          base_curve: baseCurve !== '' ? parseFloat(baseCurve) : null,
          addition: addition !== '' ? parseFloat(addition) : null,
          eye: 'OD',
          quantity: parseInt(qtyOD) || 1,
          quantity_available: parseInt(qtyOD) || 1,
          location_tag: locationTag || 'GAVETA-UNIFICADA'
        });
        // Registra OE
        await InventoryService.registerFallback({
          barcode: `${baseCode}-OE`,
          lens_model_id: modelIdToUse,
          spherical: 0.0,
          cylindrical: 0.0,
          base_curve: baseCurve !== '' ? parseFloat(baseCurve) : null,
          addition: addition !== '' ? parseFloat(addition) : null,
          eye: 'OE',
          quantity: parseInt(qtyOE) || 1,
          quantity_available: parseInt(qtyOE) || 1,
          location_tag: locationTag || 'GAVETA-UNIFICADA'
        });
      } else {
        const finalEye = isMultifocal ? (eye || 'OD') : null;
        const qToUse = (isMultifocal && eye === 'OE') ? (parseInt(qtyOE) || 1) : (isMultifocal && eye === 'OD') ? (parseInt(qtyOD) || 1) : (parseInt(quantity) || 1);
        await InventoryService.registerFallback({
          barcode: baseCode,
          lens_model_id: modelIdToUse,
          spherical: spherical !== '' ? parseFloat(spherical) : 0.0,
          cylindrical: cylindrical !== '' ? parseFloat(cylindrical) : 0.0,
          base_curve: baseCurve !== '' ? parseFloat(baseCurve) : null,
          addition: addition !== '' ? parseFloat(addition) : null,
          eye: finalEye,
          quantity: qToUse,
          quantity_available: qToUse,
          location_tag: locationTag || 'GAVETA-UNIFICADA'
        });
      }

      setFeedback({ 
        type: 'success', 
        message: `Lente '${bipBrand || 'Marca'}' (Grade: ${bipMatrixType}) gravada com sucesso no estoque!` 
      });
      setBarcode('');
      setSpherical('');
      setCylindrical('');
    } catch (err) {
      console.error(err);
      setFeedback({ type: 'error', message: formatErrorMessage(err, "Erro ao salvar item em estoque.") });
    } finally {
      setSaving(false);
    }
  };

  // Salva Modelo de Preset e Registra Dioptria no Estoque
  const handleSavePresetModel = async (e) => {
    e.preventDefault();
    const finalBrand = customBrand.trim() || selectedPresetObj?.name || 'Marca Própria';
    if (!finalBrand) {
      alert("Informe a Marca da Lente.");
      return;
    }
    setSaving(true);
    setFeedback(null);
    try {
      // 1. Cria ou obtém o modelo de lente com Marca especificada pelo usuário
      const modelPayload = {
        brand: finalBrand,
        name: finalBrand,
        material: customMaterial || selectedPresetObj?.material || 'Resina',
        refractive_index: parseFloat(customRefractiveIndex || selectedPresetObj?.index || 1.56),
        treatment: customTreatment || selectedPresetObj?.treatment || 'Incolor',
        diameter: 70,
        matrix_type: matrixType,
        production_route: selectedPresetObj?.route || 'EXPRESSA_FACETAMENTO',
        cost_price: parseFloat(costPrice) || 25.00,
        sale_price: parseFloat(salePrice) || 75.00,
        degree_threshold: parseFloat(degreeThreshold || 2.00),
        sale_price_over_threshold: parseFloat(salePriceOverThreshold || 95.00)
      };
      const modelRes = await LensService.createModel(modelPayload);
      const createdModel = modelRes.data;

      // 2. Se informado o grau, insere a dioptria diretamente no estoque
      if (presetSpherical !== '' || presetCylindrical !== '' || presetAddition !== '' || presetBaseCurve !== '') {
        const basePresetCode = (presetBarcode && presetBarcode.trim()) ? presetBarcode.trim() : 'INT-' + Math.floor(1000000000 + Math.random() * 9000000000);
        const isPresetMultifocal = (matrixType === 'MF_ACB' || matrixType === 'MF_BLOCO');

        if (isPresetMultifocal && presetEye === 'OD_OE') {
          // Registra OD
          await InventoryService.registerFallback({
            barcode: `${basePresetCode}-OD`,
            lens_model_id: createdModel.id,
            spherical: 0.0,
            cylindrical: 0.0,
            base_curve: presetBaseCurve !== '' ? parseFloat(presetBaseCurve) : null,
            addition: presetAddition !== '' ? parseFloat(presetAddition) : null,
            eye: 'OD',
            quantity_available: parseInt(presetQtyOD) || 1,
            quantity: parseInt(presetQtyOD) || 1,
            location_tag: presetLocationTag || 'GAVETA-01'
          });
          // Registra OE
          await InventoryService.registerFallback({
            barcode: `${basePresetCode}-OE`,
            lens_model_id: createdModel.id,
            spherical: 0.0,
            cylindrical: 0.0,
            base_curve: presetBaseCurve !== '' ? parseFloat(presetBaseCurve) : null,
            addition: presetAddition !== '' ? parseFloat(presetAddition) : null,
            eye: 'OE',
            quantity_available: parseInt(presetQtyOE) || 1,
            quantity: parseInt(presetQtyOE) || 1,
            location_tag: presetLocationTag || 'GAVETA-01'
          });
        } else {
          const finalPresetEye = isPresetMultifocal ? (presetEye || 'OD') : null;
          const pqToUse = (isPresetMultifocal && presetEye === 'OE') ? (parseInt(presetQtyOE) || 1) : (isPresetMultifocal && presetEye === 'OD') ? (parseInt(presetQtyOD) || 1) : (parseInt(presetQuantity) || 1);
          await InventoryService.registerFallback({
