                      value={presetAddition}
                      onChange={(e) => setPresetAddition(e.target.value)}
                      style={{ color: 'black', fontWeight: 'bold', fontSize: '1rem' }}
                    />
                  </div>
                )}

                {/* Olho -> MF_ACB, MF_BLOCO */}
                {(matrixType === 'MF_ACB' || matrixType === 'MF_BLOCO') && (
                  <div className="form-group">
                    <label className="form-label" style={{ fontWeight: 'bold', color: '#1e40af' }}>Olho (D/E) *</label>
                    <select 
                      className="form-control"
                      value={presetEye || 'OD'}
                      onChange={(e) => setPresetEye(e.target.value)}
                      style={{ color: 'black', fontWeight: 600 }}
                    >
                      <option value="OD">Somente OD (Olho Direito)</option>
                      <option value="OE">Somente OE (Olho Esquerdo)</option>
                      <option value="OD_OE">Par Completo (OD + OE Simultâneo)</option>
                    </select>
                  </div>
                )}
                <div className="form-group">
                  <label className="form-label">Gaveta / Localização</label>
                  <input 
                    type="text" 
                    placeholder="GAVETA-01"
                    className="form-control"
                    value={presetLocationTag}
                    onChange={(e) => setPresetLocationTag(e.target.value)}
                    style={{ color: 'black' }}
                  />
                </div>
              </div>
            </div>

            {/* Valores Financeiros e Quantidade Base */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '20px' }}>
              <div className="form-group">
                <label className="form-label" style={{ fontWeight: 'bold' }}>Preço de Custo (R$)</label>
                <input 
                  type="number" 
                  step="0.01"
                  className="form-control"
                  value={costPrice}
                  onChange={(e) => setCostPrice(e.target.value)}
                  style={{ color: 'black' }}
                />
              </div>

              {/* Preço de Venda manual para Matrizes não-LP (Multifocal, 1.67, Blocos, etc.) */}
              {matrixType !== 'LP_GRADE' && (
                <div className="form-group">
                  <label className="form-label" style={{ fontWeight: 'bold', color: 'hsl(var(--primary))' }}>
                    💰 Preço de Venda (R$)
                  </label>
                  <input 
                    type="number" 
                    step="0.01"
                    placeholder="0.00"
                    className="form-control"
                    value={salePrice}
                    onChange={(e) => setSalePrice(e.target.value)}
                    style={{ color: 'black', fontWeight: 'bold', fontSize: '1rem' }}
                    required
                  />
                </div>
              )}

              <div className="form-group">
                <label className="form-label" style={{ fontWeight: 'bold', color: 'hsl(var(--primary))' }}>
                  📦 Quantidade de Lentes a Inserir
                </label>
                <input 
                  type="number" 
                  min="1"
                  className="form-control"
                  value={presetQuantity}
                  onChange={(e) => setPresetQuantity(e.target.value)}
                  style={{ color: 'black', fontWeight: 'bold', background: 'rgba(59,130,246,0.06)', border: '1px solid rgba(59,130,246,0.4)' }}
                  required
                />
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '20px' }}>
              <button type="submit" className="btn btn-primary" disabled={saving} style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '10px 24px' }}>
                {saving ? "Cadastrando..." : <><Check size={18} /> Cadastrar Modelo na Matriz</>}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}
